from preserve import R,OLD,sha,inventory
from register import dump
import json,statistics
def main():
    reg=json.loads((R/'REGISTRATION.json').read_text());drift=[p for p,h in reg['files'].items() if sha(R/p)!=h];preserved=json.loads((R/'preservation/FAILED_RUN_MANIFEST.json').read_text());oldnow=inventory();changed=[p for p,v in preserved['files'].items() if oldnow.get(p)!=v];added=sorted(set(oldnow)-set(preserved['files']));archive_ok=sha(R/'preservation/failed-c16-kh.zip')==preserved['archive_sha256']
    arms={a:json.loads((R/'results'/a/'RESULT.json').read_text()) for a in ['tanakh','medieval']};g0=not drift and not changed and not added and archive_ok;passed=g0 and all(v['passed'] for v in arms.values())
    result=dict(status='QUALIFIED_LIMITED_CONTROLS' if passed else 'NOT_QUALIFIED',G0=g0,gates={a:v['gates'] for a,v in arms.items()},failed_run_preserved=not changed and not added,archive_hash_matches=archive_ok,old_file_drift=changed,old_added_files=added,qualification_file_drift=drift,ZL='CLOSED',actual_C11='CLOSED',new_ZL_scores=0,confirmation_bank_exposed=True,retuned=False,registration_sha256=sha(R/'REGISTRATION.json'),next_step='Freeze a separate prospective rerun receipt before any manuscript run.' if passed else 'Stop. Preserve failed gates. A new candidate requires separate registration and disjoint confirmation data.')
    dump(R/'QUALIFICATION.json',result)
    if passed:
        dump(R/'PROSPECTIVE_RERUN_FREEZE.json',dict(qualification_sha256=sha(R/'QUALIFICATION.json'),registration_sha256=sha(R/'REGISTRATION.json'),scorer_sha256=sha(R/'corrected.py'),legacy_search_sha256=sha(R/'inputs/legacy_core.py'),directions='unchanged 24',no_old_outputs_reused=True,original_failed_run='immutable',scope='new separate C16-KH run only after loading and checking this qualification',ZL_run_performed=False))
    rows=['# C16-KH scoring diagnosis and qualification','',f"**{result['status']} — ZL and actual C11 remain CLOSED.** New ZL scores: 0. No failed-run file was overwritten; no human rating or translation claim.",'',
    'The failed implementation used hapax mass where the published base solver adds one singleton UNKNOWN training sentence. It gave each unseen string the aggregate unknown mass, failed to canonicalize unknown histories, lost higher-order probability mass in missing contexts, and averaged EOS as another ranking slot. The defective word score also affected fitted keys. A ranking-only repair would therefore be insufficient. Source: [Hauer et al. 2014, section 3](https://aclanthology.org/C14-1218/).','',
    'The frozen correction uses one observed UNKNOWN event, canonical OOV contexts/predictions, normalized fallback distributions and a word-slot ranking denominator excluding EOS. Candidate lists, beam/search limits, normalization and all 24 variants remain unchanged. No penalties or filters were selected after qualification outcomes. [PROTOCOL.md](PROTOCOL.md) and [REGISTRATION.json](REGISTRATION.json) preserve the rules and hashes.','',
    '| Arm | G1 mathematics | G2 held-out/oracle | G3 order/invariance | G4 actual-null maxima | G5 fitted cipher |','|---|---|---|---|---|---|']
    for a,v in arms.items():rows.append('| '+a+' | '+' | '.join('PASS' if v['gates'][g] else 'FAIL' for g in ['G1','G2','G3','G4','G5'])+' |')
    for a,v in arms.items():
        d=v['details'];rows+=['',f'## {a}','',f"Probability normalization maximum error: {d['mechanics']['max_normalization_error']:.3g}; UNKNOWN count: {d['mechanics']['UNKNOWN_count']}; exhaustive Viterbi and traversal conservation: {d['mechanics']['exhaustive_Viterbi']}/{d['mechanics']['slot_conservation']}.",'',f"Held-out oracle decoding: {d['G2']['IV_accuracy']:.2%} of in-vocabulary tokens and {d['G2']['all_token_accuracy']:.2%} of all tokens recovered. Original beats quarter-UNKNOWN on {d['G2']['original_beats_quarter']}/{d['G2']['confirmation_lines']} lines; all-UNKNOWN on {d['G2']['original_beats_all']}/{d['G2']['confirmation_lines']}. All-UNKNOWN envelope selections: {d['G2']['all_UNKNOWN_envelope_selected']}; all-UNKNOWN document wins: {d['G2']['all_UNKNOWN_document_wins']}.",'',f"Natural-order maxima beat independently maximized word shuffles: {d['G3']['paired_document_wins']}/40; within-word shuffle invariance: {d['G3']['within_word_invariance']}. Neither character-shuffle equality nor unknown agreement is evidence of semantics.",'','| Null | Version | Positive exceed /40 | Null exceed /n | Null 95% Wilson interval | AUC |','|---|---|---:|---:|---|---:|']
        for r in d['G4']:rows.append(f"| {r['family']}{' (short C17)' if r['size_mismatch'] else ''} | {r['version']} | {r['positive_exceed']} | {r['false_positive']}/{r['null_n']} | {r['false_positive_interval'][0]:.1%}–{r['false_positive_interval'][1]:.1%} | {r['AUC']:.3f} |")
        rates=[x['alphagram_recovery'] for x in d['G5']];rows+=['',f"Blind search on 6 known-key ciphertexts: median alphagram recovery {statistics.median(rates):.2%}, minimum {min(rates):.2%}. Individual recoveries: "+', '.join(f'{r:.2%}' for r in rates)+'. True-key-vs-100-wrong-key counts: '+', '.join(str(x['wrong_keys_lower']) for x in d['G5'])+'. Search limits were not increased after failures.']
    rows+=['','## Preservation and limits','',f"G0 preservation: {g0}. Archived {len(preserved['files'])} original files; archive SHA256 `{preserved['archive_sha256']}`. Original sealed key was not opened. No new ZL or actual C11 data entered this scorer. Actual C11 is held because its alphagrams preserve Voynich content; Hebrew-only C11-style controls test the required equality without circumventing the hold.",'',
    'Each arm has 40 calibration and 40 confirmation Hebrew documents of 8 distinct held-out lines. Exact training-segment duplicates and exact test duplicates were excluded. Prior v1 aggregate exposure, same-work overlap, corpus editions and ordinary phrase overlap remain limitations. Nulls retain 20 calibration/20 confirmation C1/C9 pages and 19/19 C17 writers, without padding; noise uses clean fitted keys. These small finite banks cannot establish a population false-positive bound of 5%. Their confidence intervals and maximum-over-variant results remain visible. The confirmation bank is now exposed and must not be reused as fresh evidence after tuning.','',
    'Scorer mechanics, held-out discrimination and cipher search are separate gates. A mathematical repair alone does not authorize a manuscript rerun. All failed cells remain failures, without pooling or replacement. '+result['next_step'],'',
    'Artifacts: DIAGNOSIS.json; QUALIFICATION.json; results/<arm>/RESULT.json; complete variant-source.csv, Hebrew-maxima.csv and null-maxima.csv; individual known-cipher gold/fitted keys and recovery receipts; preservation/FAILED_RUN_MANIFEST.json and failed-c16-kh.zip. Reproduction: register.py is write-once; run qualify.py once for each arm, then finalize.py. Do not overwrite exposed banks.']
    (R/'REPORT.md').write_text('\n'.join(rows)+'\n',encoding='utf8');print(json.dumps(result,indent=2))
if __name__=='__main__':main()
